// Bundled PDF generation: works without a browser print dialog or external service.
export function illustrationFor(i){const n=i.name.toLowerCase();if(i.type==='pooja')return 'pooja-cnc';if(n.includes('pooja')&&n.includes('drawer'))return 'pooja-drawers';if(n.includes('cushion'))return 'cushion-box';if(n.includes('dishwasher'))return 'appliance-tower';if(n.includes('crockery'))return 'crockery';if(n.includes('pantry storage'))return 'pantry';if(n==='tall unit')return 'tall-pantry';if(n==='base unit')return 'kitchen-base';if(n.includes('wardrobe'))return 'wardrobe';if(i.type==='loft')return 'loft';if(i.type==='mirror')return 'mirror';if(i.type==='desk')return 'study-table';if(n.includes('louver'))return 'louver';if(n.includes('tv')&&n.includes('panel'))return 'tv-panel';if(n.includes('tv')&&n.includes('box unit'))return 'tv-box';if(n.includes('side glass'))return 'glass-display';if(n.includes('side open'))return 'open-display';if(n.includes('walk-in')&&n.includes('drawer'))return 'drawer-shelves';if(n.includes('walk-in'))return 'walk-in-open';if(n.includes('cnc')||n==='glass shutters')return 'cnc-glass';if(i.type==='glass')return n.includes('wall')?'wall-glass':'glass-showcase';if(n.includes('wall')||n.includes('top box'))return 'wall-box';throw new Error('Missing illustration for '+i.name);}
const plain=s=>String(s??'').replace(/₹/g,'Rs. ').replace(/[−–—]/g,'-').replace(/\u00a0/g,' ').replace(/[^\x20-\x7e\xa0-\xff\n]/g,' ');
const money=v=>'Rs. '+Number(v).toLocaleString('en-IN',{minimumFractionDigits:2,maximumFractionDigits:2});
export async function createQuotationPDF({items,houses,location,option,price,included,finish,onProgress=()=>{}}){
 const {PDFDocument,StandardFonts,rgb}=globalThis.PDFLib;if(!PDFDocument)throw new Error('PDF tools did not load. Refresh this page and retry.');
 const doc=await PDFDocument.create();doc.setTitle('Olive Tree Interiors - Mr. Pradap - Perur');doc.setAuthor('Olive Tree Interiors');const regular=await doc.embedFont(StandardFonts.Helvetica),bold=await doc.embedFont(StandardFonts.HelveticaBold);const green=rgb(.17,.30,.23),muted=rgb(.40,.45,.38),pale=rgb(.94,.96,.92),ink=rgb(.12,.18,.14);const pictures=new Map();
 for(const kind of new Set(items.map(illustrationFor))){const response=await fetch('./quote-photos/'+kind+'.jpg');if(!response.ok)throw new Error('Unable to load '+kind+' picture. Please retry.');pictures.set(kind,await doc.embedJpg(await response.arrayBuffer()));}
 function text(page,s,x,y,size=9,font=regular,color=ink){page.drawText(plain(s),{x,y,size,font,color});}
 function wrap(s,width,size=9,font=regular){let lines=[],line='';for(const word of plain(s).split(/\s+/)){const next=line?line+' '+word:word;if(font.widthOfTextAtSize(next,size)>width&&line){lines.push(line);line=word}else line=next;}if(line)lines.push(line);return lines;}
 function lines(page,s,x,y,width,size=9,font=regular,color=ink){const a=wrap(s,width,size,font);for(const l of a){text(page,l,x,y,size,font,color);y-=size*1.35;}return y;}
 const basePage=(title,room='')=>{const page=doc.addPage([595.28,841.89]);page.drawRectangle({x:0,y:765,width:595.28,height:77,color:green});text(page,'Olive Tree Interiors',30,810,20,bold,rgb(1,1,1));text(page,'Mr. Pradap | Perur | Interior quotation',30,788,10,regular,rgb(1,1,1));text(page,title,30,744,12,bold);text(page,room,30,727,10,bold,green);text(page,'Option '+(option+1)+' | Measurements in feet | Rates per sq.ft',30,710,8,regular,muted);return page;};
 let total=0,excluded=0;const totals=[];
 const roomName=i=>i.room==='unassigned'?'Wardrobe (room pending)':i.room==='pooja'?'Pooja room':i.room==='master'?'Bedroom 1'+(i.house==='ground'?' - Master bedroom':''):({kitchen:'Kitchen',bedroom2:'Bedroom 2',bedroom3:'Bedroom 3',hall:'Hall'}[i.room]||i.room);
 for(const house of houses){const entries=items.filter(i=>i.house===house.key);let subtotal=0;for(const i of entries){if(included(i))subtotal+=price(i);else excluded+=price(i);}total+=subtotal;totals.push([house.name,subtotal]);const roomTotals=[];
 for(const key of new Set(entries.map(i=>i.room))){const roomEntries=entries.filter(i=>i.room===key),label=roomName(roomEntries[0]),roomTotal=roomEntries.reduce((sum,i)=>sum+(included(i)?price(i):0),0);roomTotals.push([label,roomTotal]);
 for(let start=0;start<roomEntries.length;start+=3){const page=basePage(house.name,label+(start?' - continued':''));for(const [j,i]of roomEntries.slice(start,start+3).entries()){const top=687-j*211,bottom=top-197;page.drawRectangle({x:26,y:bottom,width:543,height:197,color:rgb(1,1,1),borderColor:rgb(.80,.84,.78),borderWidth:.8});page.drawRectangle({x:27,y:top-26,width:541,height:25,color:pale});text(page,location(i),38,top-17,8,bold,green);
 let y=lines(page,i.id+'. '+i.name,38,top-44,310,12,bold);y-=4;text(page,i.size+' | '+i.area+' sq.ft',38,y,9);y-=16;text(page,money(i.rate*[1,.85,1.18][option])+' / sq.ft',38,y,9);y-=18;text(page,money(price(i))+' - '+(included(i)?'INCLUDED':i.id===7?'OPTIONAL / EXCLUDED':'EXCLUDED'),38,y,11,bold,included(i)?green:rgb(.6,.25,.19));y-=17;y=lines(page,i.spec,38,y,305,8);y-=4;y=lines(page,'2 mm edge banding on applicable board edges; factory finishing.',38,y,305,8,regular,muted);y-=4;lines(page,finish(i),38,y,305,7,regular,muted);
 const image=pictures.get(illustrationFor(i));const imageScale=Math.min(197/image.width,138/image.height);page.drawImage(image,{x:360+(197-image.width*imageScale)/2,y:bottom+23+(138-image.height*imageScale)/2,width:image.width*imageScale,height:image.height*imageScale});text(page,'Photo-style design reference',375,bottom+10,7,regular,muted);

 }if(start+3>=roomEntries.length){page.drawRectangle({x:27,y:42,width:541,height:23,color:pale});text(page,label+' TOTAL',37,50,9,bold,green);const value=money(roomTotal);text(page,value,557-bold.widthOfTextAtSize(value,10),50,10,bold,green);}onProgress(Math.min(items.length,start+3),items.length);}
 }
 const housePage=basePage(house.name+' - house summary','HOUSE COMPLETE');let y=665;for(const [label,value]of roomTotals){housePage.drawRectangle({x:27,y:y-12,width:541,height:37,color:pale});text(housePage,label,39,y,10,bold);const amount=money(value);text(housePage,amount,557-bold.widthOfTextAtSize(amount,10),y,10,bold);y-=46;}
 housePage.drawRectangle({x:27,y:y-47,width:541,height:78,color:green});text(housePage,'HOUSE GRAND TOTAL',40,y+9,12,bold,rgb(1,1,1));const amount=money(subtotal);text(housePage,amount,555-bold.widthOfTextAtSize(amount,20),y-22,20,bold,rgb(1,1,1));housePage.drawLine({start:{x:27,y:y-60},end:{x:568,y:y-60},thickness:4,color:rgb(.77,.64,.33)});lines(housePage,'End of '+house.name+'. Optional and excluded items do not contribute to these totals.',35,y-83,520,9,regular,muted);
 }
 const summary=basePage('Quotation summary');let y=685;for(const [name,value]of totals){text(summary,name,35,y,12,bold);text(summary,money(value),350,y,12,bold);y-=42;}summary.drawRectangle({x:27,y:y-37,width:542,height:64,color:green});text(summary,'Selected quotation total',40,y+2,12,bold,rgb(1,1,1));text(summary,money(total),350,y+2,17,bold,rgb(1,1,1));y-=78;y=lines(summary,'Excluded / optional items: '+money(excluded)+'. These do not contribute to the selected total.',35,y,510,10);y-=20;y=lines(summary,'Images are AI-generated realistic design references. Final dimensions, finishes, hardware and internal arrangements follow the written specification and approved design.',35,y,510,10);y-=20;lines(summary,'Selected colours and exclusions reflect this quotation option at the time the PDF was generated. Optional crockery is included only when selected.',35,y,510,10);
 const pages=doc.getPages();pages.forEach((p,k)=>{text(p,'Olive Tree Interiors | Mr. Pradap, Perur',30,25,8,regular,muted);text(p,(k+1)+' / '+pages.length,520,25,8,regular,muted)});return doc.save();
}
export async function showQuotationPDF(options){
 let old=document.getElementById('quotationPDF');if(old)old.remove();const panel=document.createElement('section');panel.id='quotationPDF';panel.className='pdf-overlay';panel.setAttribute('role','dialog');panel.setAttribute('aria-modal','true');panel.setAttribute('aria-label','Quotation PDF');panel.innerHTML='<div class="pdf-panel"><div class="pdf-heading"><h2>Your quotation PDF</h2><button data-close>Close</button></div><p data-message role="status">Preparing your quotation with item pictures…</p><div data-actions hidden><a data-download>Download PDF</a><button data-share>Save / Share PDF</button><a data-open target="_blank" rel="noopener">Open PDF / Print</a></div><iframe title="Quotation PDF preview" hidden></iframe></div>';document.body.append(panel);const previousOverflow=document.body.style.overflow;document.body.style.overflow='hidden';let url;panel.querySelector('[data-close]').onclick=()=>{document.body.style.overflow=previousOverflow;panel.remove();if(url)URL.revokeObjectURL(url)};
 try{const bytes=await createQuotationPDF(options);const blob=new Blob([bytes],{type:'application/pdf'});url=URL.createObjectURL(blob);const name='Olive_Tree_Pradap_Perur_Quotation.pdf';const download=panel.querySelector('[data-download]');download.href=url;download.download=name;panel.querySelector('[data-open]').href=url;panel.querySelector('[data-actions]').hidden=false;panel.querySelector('[data-message]').textContent='Your PDF is ready. Download it, save it through Share, or open it to print.';const frame=panel.querySelector('iframe');frame.src=url;frame.hidden=false;panel.querySelector('[data-share]').onclick=async()=>{try{const file=new File([blob],name,{type:'application/pdf'});if(navigator.canShare?.({files:[file]})){await navigator.share({files:[file],title:'Olive Tree Interiors quotation'});}else download.click();}catch(e){if(e.name!=='AbortError')panel.querySelector('[data-message]').textContent='Use Download PDF or Open PDF / Print to save this file.';}};
 }catch(e){panel.querySelector('[data-message]').textContent='Could not prepare PDF: '+e.message+' Close this window and retry.';}
}
